import * as THREE from 'three';
// Canvas painter fallback for environments without WebGL. No shadows/PBR; geometry and texture UVs retained.
export class SoftwareRenderer{
constructor(){this.domElement=document.createElement('canvas');this.ctx=this.domElement.getContext('2d');this.shadowMap={};this.capabilities={getMaxAnisotropy:()=>1};this.isSoftware=true;this.last=0;this.bg='#e9ede7'}setPixelRatio(){}setClearColor(c){this.bg='#'+c.toString(16).padStart(6,'0')}setSize(w,h){this.domElement.width=w;this.domElement.height=h}
render(scene,camera){const now=performance.now();if(now-this.last<65)return;this.last=now;scene.updateMatrixWorld();camera.updateMatrixWorld();const w=this.domElement.width,h=this.domElement.height,ctx=this.ctx;ctx.fillStyle=this.bg;ctx.fillRect(0,0,w,h);const light=scene.children.find(o=>o.isDirectionalLight),ambient=scene.children.find(o=>o.isHemisphereLight),lightDir=light?light.position.clone().normalize():new THREE.Vector3(1,1,1).normalize();const faces=[],v=[new THREE.Vector3(),new THREE.Vector3(),new THREE.Vector3()];let total=0;
scene.traverse(o=>{if(!o.isMesh||!o.visible||o.geometry.type==='PlaneGeometry'&&o.geometry.parameters.width>500)return;const g=o.geometry,p=g.attributes.position;if(!p)return;const ids=g.index,uv=g.attributes.uv,count=ids?ids.count:p.count;if(total+count/3>30000)return;total+=count/3;for(let i=0;i<count;i+=3){let mats=Array.isArray(o.material)?o.material:null,m=o.material;if(mats){const group=g.groups.find(q=>i>=q.start&&i<q.start+q.count);m=mats[group?group.materialIndex:0]}if(!m||!m.visible)continue;const indices=[0,1,2].map(k=>ids?ids.getX(i+k):i+k);for(let k=0;k<3;k++)v[k].fromBufferAttribute(p,indices[k]).applyMatrix4(o.matrixWorld).project(camera);if(v.some(q=>q.z<-1||q.z>1))continue;const world=indices.map(j=>new THREE.Vector3().fromBufferAttribute(p,j).applyMatrix4(o.matrixWorld)),normal=new THREE.Vector3().subVectors(world[1],world[0]).cross(new THREE.Vector3().subVectors(world[2],world[0])).normalize(),shade=Math.min(1,Math.max(.12,(ambient?.intensity||0)*.18+(light?.intensity||0)*.19*Math.max(0,normal.dot(lightDir))));const xy=v.map(q=>[(q.x+1)*w/2,(1-q.y)*h/2]);const area=(xy[1][0]-xy[0][0])*(xy[2][1]-xy[0][1])-(xy[1][1]-xy[0][1])*(xy[2][0]-xy[0][0]);if(m.side===THREE.FrontSide&&area>0)continue;const uvs=uv?indices.map(j=>[uv.getX(j),1-uv.getY(j)]):null;faces.push({xy,shade,z:(v[0].z+v[1].z+v[2].z)/3,m,uvs})}});faces.sort((a,b)=>b.z-a.z);
for(const {xy,m,uvs,shade} of faces){ctx.save();ctx.beginPath();ctx.moveTo(...xy[0]);ctx.lineTo(...xy[1]);ctx.lineTo(...xy[2]);ctx.closePath();const img=m.map?.image;if(img&&uvs&&img.width&&img.height){const a=uvs.map(t=>[t[0]*img.width,t[1]*img.height]),[x0,y0]=a[0],[x1,y1]=a[1],[x2,y2]=a[2],det=x0*(y1-y2)+x1*(y2-y0)+x2*(y0-y1);if(Math.abs(det)>.0001){const calc=(k)=>[(xy[0][k]*(y1-y2)+xy[1][k]*(y2-y0)+xy[2][k]*(y0-y1))/det,(xy[0][k]*(x2-x1)+xy[1][k]*(x0-x2)+xy[2][k]*(x1-x0))/det,(xy[0][k]*(x1*y2-x2*y1)+xy[1][k]*(x2*y0-x0*y2)+xy[2][k]*(x0*y1-x1*y0))/det],xx=calc(0),yy=calc(1);ctx.clip();ctx.transform(xx[0],yy[0],xx[1],yy[1],xx[2],yy[2]);try{ctx.drawImage(img,0,0)}catch{} }}else{ctx.fillStyle=m.color?'#'+m.color.getHexString():'#cdd3cf';ctx.fill()}ctx.restore();if(shade<1){ctx.save();ctx.beginPath();ctx.moveTo(...xy[0]);ctx.lineTo(...xy[1]);ctx.lineTo(...xy[2]);ctx.closePath();ctx.globalCompositeOperation='multiply';ctx.fillStyle='rgba(0,0,0,'+(1-shade)+')';ctx.fill();ctx.restore()}}
}}
